// Verifica firma HMAC: X-Signature = hex(HMAC-SHA256(secret, X-Timestamp + "." + rawBody)).
// La funzione seguente è copiata identica da agenda-app/n8n/verify-signature.js
// (stesso algoritmo di verifyRequest in agenda-app/src/lib/n8n/sign.ts).
function verifyAgendaSignature(rawBody, secret, timestampMs, signature, nowMs) {
  const crypto = require('crypto');
  const MAX_SKEW_MS = 5 * 60 * 1000;
  if (!Number.isFinite(timestampMs) || Math.abs(nowMs - timestampMs) > MAX_SKEW_MS) return false;
  if (typeof signature !== 'string' || !/^[0-9a-f]{64}$/i.test(signature)) return false;
  const expected = Buffer.from(
    crypto.createHmac('sha256', secret).update(timestampMs + '.' + rawBody).digest('hex'),
    'hex',
  );
  const given = Buffer.from(signature, 'hex');
  if (expected.length !== given.length) return false;
  return crypto.timingSafeEqual(expected, given);
}

const item = $input.first();
const headers = item.json.headers || {};
let rawBody = '';
const bin = item.binary && item.binary.data;
if (bin) {
  try {
    rawBody = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
  } catch (e) {
    rawBody = Buffer.from(bin.data || '', 'base64').toString('utf8');
  }
}
const tsHeader = String(headers['x-timestamp'] ?? '');
const timestampMs = /^\d{1,16}$/.test(tsHeader) ? Number(tsHeader) : NaN;
const signature = String(headers['x-signature'] ?? '');
const secret = $vars.AGENDA_WEBHOOK_SECRET;
const authorized =
  typeof secret === 'string' &&
  secret.length > 0 &&
  verifyAgendaSignature(rawBody, secret, timestampMs, signature, Date.now());
let body = null;
if (authorized) {
  try {
    body = JSON.parse(rawBody);
  } catch (e) {
    body = null; // firma valida ma JSON non valido: lo rifiuta "Valida input" con 400
  }
}
return [{ json: { authorized, body } }];

const body = $input.first().json.body;
const fail = (message) => [{ json: { ok: false, statusCode: 400, body: { error: 'invalid_input', message } } }];
const EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const normEmail = (e) => (typeof e === 'string' ? e.trim().toLowerCase() : '');
const isDate = (s) => typeof s === 'string' && !Number.isNaN(Date.parse(s));
if (!body || typeof body !== 'object' || Array.isArray(body)) return fail('body mancante o non valido');
// Stessi limiti del client (agenda-app/src/lib/n8n/client.ts): max 15 email, max 14 giorni.
if (!Array.isArray(body.emails)) return fail('emails');
const emails = [...new Set(body.emails.map(normEmail))];
if (emails.length < 1 || emails.length > 15 || emails.some((e) => !EMAIL.test(e))) return fail('emails');
if (!isDate(body.timeMin) || !isDate(body.timeMax)) return fail('timeMin/timeMax');
const min = Date.parse(body.timeMin);
const max = Date.parse(body.timeMax);
if (!(max > min) || max - min > 14 * 24 * 60 * 60 * 1000) return fail('intervallo');
return [{ json: { ok: true, emails, timeMin: new Date(min).toISOString(), timeMax: new Date(max).toISOString() } }];

// Solo intervalli occupato/libero: nessun titolo o dettaglio di eventi esce da qui.
const calendarError = () => [{ json: { respond: true, statusCode: 502, body: { error: 'calendar_error' } } }];
const res = $input.first().json;
const { emails } = $('Valida input').first().json;
if (res.statusCode !== 200 || !res.body || typeof res.body.calendars !== 'object' || res.body.calendars === null) {
  return calendarError();
}
const source = {};
for (const [id, cal] of Object.entries(res.body.calendars)) source[id.toLowerCase()] = cal;
const calendars = {};
for (const email of emails) {
  const cal = source[email];
  if (!cal || (Array.isArray(cal.errors) && cal.errors.length > 0)) {
    // Calendario illeggibile: l'app lo tratta come occupato per tutto l'intervallo.
    const reason = cal && cal.errors[0] && cal.errors[0].reason;
    calendars[email] = { error: typeof reason === 'string' ? reason : 'notFound' };
  } else {
    calendars[email] = {
      busy: (Array.isArray(cal.busy) ? cal.busy : []).map((b) => ({ start: String(b.start), end: String(b.end) })),
    };
  }
}
return [{ json: { respond: true, statusCode: 200, body: { calendars } } }];
